function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw pineapple
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw spikes
  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    ctx.moveTo(W/2 + 50*Math.cos(i*Math.PI/4 + Math.sin(t)), H/2 + 50*Math.sin(i*Math.PI/4 + Math.sin(t)));
    ctx.lineTo(W/2 + 70*Math.cos(i*Math.PI/4 + Math.sin(t)), H/2 + 70*Math.sin(i*Math.PI/4 + Math.sin(t)));
    ctx.stroke();
  }

  // draw cutting knife
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 - 20 + 10*Math.sin(t), H/2 - 20);
  ctx.lineTo(W/2 + 20 + 10*Math.sin(t), H/2 + 20);
  ctx.stroke();

  ctx.restore();
}
